#include "stdafx.h"#include "HcdElementBase.h"struct SSUB_P{#include "PrivateVars/SUB.h"};class KSUB : public KHcdElementBase  , protected SSUB_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _SUB("SUB", KSUB::Create);IHcdElement *KSUB::Create(){  return new KSUB;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KSUB, 3 )void KSUB::InitParm(){#include "PrivateVars/SUB.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KSUB::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KSUB::StepCalc( SStepCalcParams &params ){  OUTD0 = INU0 - INL0;}